begin;
create function public.fixture_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'SQL_CONTRACT_FAILED: %',label;end if;end$$;
insert into auth.users select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,8)n;
insert into auth.sessions select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=8 then now()-interval '1 hour' else now()+interval '1 day' end from generate_series(1,8)n;
insert into scenario_private.projects(id,owner_id,collaboration) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',true),('20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000005',true);
insert into scenario_private.memberships(project_id,account_id,role,expires_at,revoked_at) select '20000000-0000-4000-8000-000000000001',('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 1 then 'owner' when 2 then 'editor' when 3 then 'reviewer' else 'reader' end,case when n=6 then now()-interval '1 hour' end,case when n=7 then now() end from generate_series(1,8)n where n<>5;
insert into scenario_private.documents(project_id,id,revision,document) select '20000000-0000-4000-8000-000000000001',('30000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,0,jsonb_build_object('fields',jsonb_build_object('visibility',case n when 1 then 'private' else 'team' end,'name',case n when 1 then 'SECRET_CANARY' else 'TEAM' end)) from generate_series(1,2)n;
insert into public.scenario_snapshots(id,public_project_id,projection,content_hash) values('40000000-0000-4000-8000-000000000001','public-story','{"entities":[{"id":"public-note","kind":"note","data":{"body":[{"id":"public-block","text":"😀公開"}]}}],"relations":[{"id":"public-line"}]}',repeat('a',64));
insert into scenario_private.snapshot_bindings values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',repeat('b',64));
insert into scenario_private.snapshot_grants(snapshot_id,account_id) select '40000000-0000-4000-8000-000000000001',('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(2,8)n;
insert into scenario_private.assets values('20000000-0000-4000-8000-000000000001',repeat('a',64),4,'text/plain','private','20000000-0000-4000-8000-000000000001/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',true),('20000000-0000-4000-8000-000000000001',repeat('b',64),4,'text/plain','team','20000000-0000-4000-8000-000000000001/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',true);
insert into storage.objects(bucket_id,name) select 'scenario-private',storage_path from scenario_private.assets;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select public.fixture_assert((select count(*)=2 from scenario_private.documents),'owner author records');
select public.fixture_assert((select count(*)=2 from storage.objects),'owner private bytes');
select public.fixture_assert((select count(*)=1 from public.scenario_snapshots),'owner limited snapshot');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002"}',true);
select public.fixture_assert((select count(*)=0 from scenario_private.documents),'editor uses granted fieldset; canonical image unavailable');
select public.fixture_assert((select count(*)=0 from scenario_private.documents where document::text like '%SECRET_CANARY%'),'editor no secret text/count');
select public.fixture_assert((select count(*)=0 from storage.objects),'editor requires approved snapshot bytes');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003"}',true);
select public.fixture_assert((select count(*)=0 from scenario_private.documents),'reviewer author refusal');
select public.fixture_assert((select count(*)=0 from storage.objects),'reviewer canonical byte refusal');
select public.fixture_assert((select count(*)=1 from public.scenario_snapshots),'reviewer public snapshot');
insert into public.scenario_comments(id,snapshot_id,public_entity_id,public_block_id,start_cp,end_cp,body) values('60000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','public-note','public-block',0,1,'😀位置への指摘');
update public.scenario_comments set body='更新した指摘' where id='60000000-0000-4000-8000-000000000001';
select public.fixture_assert((select body='更新した指摘' from public.scenario_comments),'own comment edit');
do $$begin begin insert into public.scenario_comments(snapshot_id,public_entity_id,body) values('40000000-0000-4000-8000-000000000001','SECRET_CANARY','不可');raise exception 'unexpected secret comment';exception when raise_exception then if sqlerrm<>'PUBLIC_TARGET_UNKNOWN' then raise;end if;end;end$$;
do $$begin begin insert into public.scenario_comments(snapshot_id,public_entity_id,public_block_id,start_cp,end_cp,body) values('40000000-0000-4000-8000-000000000001','public-note','public-block',0,4,'範囲外');raise exception 'unexpected Unicode position';exception when raise_exception then if sqlerrm<>'PUBLIC_TARGET_UNKNOWN' then raise;end if;end;end$$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004"}',true);
select public.fixture_assert((select count(*)=1 from public.scenario_comments),'reader approved comments only');
update public.scenario_comments set body='他人の上書き';select public.fixture_assert((select body='更新した指摘' from public.scenario_comments),'reader cannot overwrite');
do $$begin begin insert into public.scenario_comments(snapshot_id,public_entity_id,body) values('40000000-0000-4000-8000-000000000001','public-note','不可');raise exception 'unexpected reader write';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000005","session_id":"10000000-0000-4000-8000-000000000005"}',true);
select public.fixture_assert((select count(*)=0 from public.scenario_snapshots),'other project/nonmember snapshot refusal');
select public.fixture_assert((select count(*)=0 from scenario_private.documents),'other project author refusal');
select public.fixture_assert((select count(*)=0 from storage.objects),'other project byte refusal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000006","session_id":"10000000-0000-4000-8000-000000000006"}',true);
select public.fixture_assert((select count(*)=0 from public.scenario_snapshots),'membership expiry');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000007","session_id":"10000000-0000-4000-8000-000000000007"}',true);
select public.fixture_assert((select count(*)=0 from public.scenario_snapshots),'membership revoked');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000008","session_id":"10000000-0000-4000-8000-000000000008"}',true);
select public.fixture_assert((select count(*)=0 from public.scenario_snapshots),'expired real session fixture');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
select public.fixture_assert((select count(*)=0 from scenario_private.documents),'missing session refused');
reset role;
update public.scenario_snapshots set withdrawn_at=now();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select public.fixture_assert((select count(*)=0 from public.scenario_snapshots),'withdrawn projection refused');
select public.fixture_assert((select count(*)=0 from public.scenario_comments),'withdrawn comment refused');
reset role;
select public.fixture_assert((select public=false from storage.buckets where id='scenario-private'),'private bucket');
select public.fixture_assert(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('scenario_private','public') and c.relkind='r' and c.relname<>'fixture_assert' and not c.relrowsecurity),'RLS all product tables');
commit;
